from solution import SafeCounter

def test_concurrent_increments():
    counter = SafeCounter()
    threads = [threading.Thread(target=lambda: [counter.increment() for _ in range(1000)]) for _ in range(10)]
    for t in threads:
        t.start()
    for t in threads:
        t.join()
    assert counter.value() == 10000

